(function(){'use strict';var currentFrame=null;function post(command){if(currentFrame&&currentFrame.contentWindow)currentFrame.contentWindow.postMessage(Object.assign({source:'nawaf-hq-dashboard'},command),'*')}function boot(){var wrap=document.querySelector('.hq-3d-stage');if(!wrap||wrap.dataset.v18Live==='1')return;wrap.dataset.v18Live='1';var old=wrap.querySelector('.office-scene');if(old)old.remove();var frame=document.createElement('iframe');frame.src='hq-office-live.html?v=18-local-three-1';frame.className='live-office-frame';frame.title='NAWAF HQ live office V18';frame.style.position='absolute';frame.style.inset='0';frame.style.width='100%';frame.style.height='100%';frame.style.border='0';frame.style.zIndex='2';frame.style.background='#101720';wrap.prepend(frame);currentFrame=frame;wrap.querySelectorAll('.room-nav,.scene-brand,.scene-status').forEach(function(n){n.style.display='none'});wrap.style.minHeight='620px'}function indexOfEmployee(id){try{var s=JSON.parse(localStorage.getItem('nawaf-hq-v5')||'{}');var i=(s.employees||[]).findIndex(function(e){return e.id===id});return i<0?0:i}catch(e){return 0}}function routeEmployee(id,status){try{var w=currentFrame&&currentFrame.contentWindow,api=w&&w.NawafOfficeV15,T=w&&w.THREE;if(!api||!api.moveEmployee||!T)return;var i=indexOfEmployee(id),slots=[[-13,-5],[-6.7,-5],[6.7,-5],[13,-5],[-13,5],[-6.7,5],[6.7,5],[13,5]],s=slots[i]||slots[0],to,mode=status||'READY';if(status==='WAITING_FOR_NAWAF'){to=new T.Vector3(-3.1+(i%4)*2.05,.12,-8.5+Math.floor(i/4)*1.3);mode='MEETING'}else if(status==='REVIEWING'){to=new T.Vector3(-2.5+(i%4)*1.7,.12,.8+Math.floor(i/4)*1.1);mode='REVIEW'}else{to=new T.Vector3(s[0]-.15,.12,s[1]-.82);mode=status==='WORKING'||status==='RESEARCHING'?status:'READY'}api.moveEmployee(id,to,mode)}catch(e){}}window.NawafHQ3D={boot:boot,mode:function(mode){post({action:'mode',mode:mode})},meeting:function(){post({action:'meeting'})},review:function(){post({action:'review'})},collab:function(){post({action:'collab'})},work:function(){post({action:'work'})},assignTask:function(employeeId,taskType){post({action:'assignTask',employeeId:employeeId,taskType:taskType})},routeEmployee:routeEmployee};function start(){setTimeout(boot,120)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start();window.addEventListener('message',function(e){var m=e.data||{};if(m.source!=='nawaf-hq-office'||!m.type)return;window.dispatchEvent(new CustomEvent(m.type,{detail:m.detail||{}}));if(m.type==='hq:office-ready')window.dispatchEvent(new CustomEvent('nawaf:office-ready',{detail:m.detail||{}}));if(m.type==='hq:office-error'){var w=document.querySelector('.hq-3d-stage');if(w)w.dataset.officeError=String(m.detail&&m.detail.reason||'UNKNOWN')}});window.addEventListener('nawaf:state-updated',function(){var w=document.querySelector('.hq-3d-stage');if(w&&w.dataset.forceOfficeReload==='1'){w.dataset.v18Live='';w.dataset.forceOfficeReload='';var f=w.querySelector('.live-office-frame');if(f)f.remove();currentFrame=null;setTimeout(boot,120)}})})();